css:
:root {
  --primary: #8ae2ff;
  --primary-hover: #5dc6ff;
  --bg: #0b1724;
  --bg-alt: #0f2131;
  --card-bg: rgba(17, 32, 48, 0.9);
  --text: #e6f5ff;
  --text-secondary: #bcd4e6;
  --border: #2f4f68;
  --glow-green: #7cf2c6;
  --glow-purple: #9d7cff;
  --frost: rgba(255,255,255,0.08);
}

body {
  background: radial-gradient(circle at 20% 10%, rgba(138,226,255,0.16), transparent 40%),
              radial-gradient(circle at 78% 0%, rgba(124,242,198,0.12), transparent 38%),
              linear-gradient(180deg, #0a1320 0%, #0c1826 45%, #0f2232 100%);
  color: var(--text);
  background-attachment: fixed;
}

.header {
  background: linear-gradient(100deg, rgba(124,242,198,0.28) 0%, rgba(138,226,255,0.35) 40%, rgba(157,124,255,0.32) 100%);
  border-bottom: 2px solid var(--primary);
  box-shadow: 0 18px 38px rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(14px) saturate(130%);
}

.brand {
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #e9fbff;
  text-shadow: 0 0 14px rgba(138,226,255,0.8), 0 0 26px rgba(124,242,198,0.5);
}

.card {
  background: linear-gradient(160deg, rgba(17, 32, 48, 0.95) 0%, rgba(19, 37, 55, 0.9) 100%);
  border: 1px solid rgba(138,226,255,0.35);
  border-radius: 18px;
  box-shadow: 0 18px 36px rgba(0,0,0,0.45);
  position: relative;
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.18s ease;
}

.card::before {
  content: "";
  position: absolute;
  inset: -30% -10% 35% -10%;
  background: radial-gradient(ellipse at 40% 30%, rgba(138,226,255,0.25) 0%, transparent 60%),
              radial-gradient(ellipse at 70% 20%, rgba(157,124,255,0.22) 0%, transparent 55%);
  filter: blur(8px);
}

.card:hover {
  transform: translateY(-5px);
  border-color: rgba(124,242,198,0.55);
  box-shadow: 0 24px 50px rgba(0,0,0,0.5);
}

.card .card-title {
  color: #f5fbff;
  letter-spacing: 0.02em;
  font-weight: 800;
}

.card .card-body {
  color: var(--text-secondary);
  line-height: 1.75;
}

.card .tag,
.card .label {
  background: linear-gradient(120deg, rgba(124,242,198,0.9) 0%, rgba(138,226,255,0.9) 50%, rgba(157,124,255,0.9) 100%);
  color: #062038;
  border: 1px solid rgba(138,226,255,0.6);
  border-radius: 999px;
  box-shadow: 0 0 16px rgba(138,226,255,0.35);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.sidebar,
.panel,
.modal,
.popover {
  background: rgba(11, 21, 32, 0.88);
  border: 1px solid rgba(138,226,255,0.25);
  box-shadow: 0 16px 34px rgba(0,0,0,0.55);
  backdrop-filter: blur(10px) saturate(120%);
}

.list-item,
.menu-item,
.dropdown-item {
  background: rgba(16, 32, 46, 0.88);
  border-radius: 12px;
  border: 1px solid rgba(124,242,198,0.25);
  transition: background 0.16s ease, transform 0.16s ease;
}

.list-item:hover,
.menu-item:hover,
.dropdown-item:hover {
  background: rgba(20, 42, 58, 0.9);
  transform: translateX(5px);
}

.progress,
.timeline::before,
.board::before {
  background: linear-gradient(90deg, rgba(138,226,255,0.35), rgba(124,242,198,0.25), rgba(157,124,255,0.35));
}

.floating-ribbon {
  background: linear-gradient(100deg, #7cf2c6 0%, #8ae2ff 50%, #9d7cff 100%);
  color: #081827;
  box-shadow: 0 16px 36px rgba(0,0,0,0.45);
}
